    "(not counted — only the top 10 bonuses apply)": "(لا يُحتسب — تُطبق أعلى 10 مكافآت إضافية فقط)",
    "/ 15 matches · Form": "/ 15 مباراة · المستوى",
    "29 cards in four original designs, with full attributes. 20 season and objective rewards, plus nine retro versions.": "29 بطاقة بأربعة تصاميم أصلية، مع السمات الكاملة. 20 مكافأة موسم وأهداف، بالإضافة إلى تسع نسخ كلاسيكية.",
    "APK in progress · 1 CLUB": "ملف APK قيد الإعداد · 1 CLUB",
    "Bonus after completing all four Marquee Matchups segments: ": "المكافأة بعد إكمال الأجزاء الأربعة من Marquee Matchups: ",
    "CLUB": "النادي",
    "Challenge formation: ": "خطة لعب التحدي: ",
    "Checked ": "تم التحقق من ",
    "D is the first grade, followed by C, B, A and S, the highest. Every slot must be filled. Thresholds vary by set and rewards are cumulative.": "D هو التقييم الأول، تليه C وB وA ثم S وهو الأعلى. يجب ملء كل خانة. تختلف الحدود حسب المجموعة والمكافآت تراكمية.",
    "Day 1 and Day 7 are measured from the first observed active day, not a historical signup date. Rates start when the required return day is reached; the current day is still partial.": "يُقاس اليوم الأول واليوم السابع من أول يوم نشاط مُسجّل، لا من تاريخ التسجيل السابق. تُحسب المعدلات عند بلوغ يوم العودة المطلوب؛ واليوم الحالي لم يكتمل بعد.",
    "Day 1 return: ": "العودة في اليوم الأول: ",
    "Day 7 return: ": "العودة في اليوم السابع: ",
    "Download APK · 1 CLUB": "تنزيل APK · 1 CLUB",
    "Drag in any direction — the area inside the circle will appear on your card": "اسحب في أي اتجاه — ستظهر المنطقة داخل الدائرة على بطاقتك",
    "EA FC chemistry: up to three diamonds per player based on club, nation and league links. An incorrect position gives 0. Maximum total: 33.": "تناغم EA FC: حتى ثلاث معينات لكل لاعب بناءً على روابط النادي والجنسية والدوري. يمنح المركز غير الصحيح 0. الحد الأقصى الإجمالي: 33.",
    "Each option is checked for item count, grade thresholds and bonuses. This is calculation validation; in-game evidence is reviewed separately for community solutions.": "يُتحقق من عدد العناصر وحدود التقييم والمكافآت الإضافية لكل خيار. هذا تحقق من الحساب؛ وتُراجع أدلة اللعبة بشكل منفصل لحلول المجتمع.",
    "Ends in ": "ينتهي خلال ",
    "Everyone is in black and white. Tap only the player who matches. Correct answers stay in color.": "الجميع بالأبيض والأسود. اضغط فقط على اللاعب المطابق. تبقى الإجابات الصحيحة بالألوان.",
    "Everyone plays their own save. Self-reported progress, without EA account sync or points for marking milestones.": "يلعب الجميع ملفات حفظهم الخاصة. يُبلّغ كل مشارك عن تقدمه، دون مزامنة حساب EA أو منح نقاط لتسجيل الإنجازات.",
    "Explore Future Stars ✦": "استكشف نجوم المستقبل ✦",
    "FC 27 SCOUTING REPORT": "تقرير استكشاف FC 27",
    "FC 27 STYLE": "أسلوب FC 27",
    "FC 27 Talent Scouting": "استكشاف مواهب FC 27",
    "FC 27 · Club community": "FC 27 · مجتمع الأندية",
    "FC27 COMMUNITY": "مجتمع FC27",
    "Find players for the time you play. Set a session, choose your platform and bring the squad together.": "اعثر على لاعبين في الوقت الذي تلعب فيه. حدد جلسة واختر منصتك واجمع التشكيلة.",
    "Find players who match your style, build a stronger squad, and play with the right people.": "اعثر على لاعبين يناسبون أسلوبك، وابنِ تشكيلة أقوى والعب مع الأشخاص المناسبين.",
    "Finish the first transfer window\nWin promotion\nQualify for Europe": "أنهِ فترة الانتقالات الأولى\nحقق الصعود\nتأهل إلى البطولات الأوروبية",
    "For example: Liverpool links and French wingers, costing approximately 12,000 coins": "مثال: روابط ليفربول وأجنحة فرنسيون، بتكلفة تقارب 12,000 عملة",
    "For example: silver cards from the Belgian league, with Belgian players for chemistry": "مثال: بطاقات فضية من الدوري البلجيكي، مع لاعبين بلجيكيين للتناغم",
    "For this challenge, share an in-game screenshot with the segment name and a short explanation.": "لهذا التحدي، شارك لقطة شاشة من داخل اللعبة تتضمن اسم الجزء وشرحًا موجزًا.",
    "Formation, captain, and five cards for every position.": "خطة اللعب والقائد وخمس بطاقات لكل مركز.",
    "GRID": "الشبكة",
    "Gold PlayStyle +": "أسلوب لعب ذهبي +",
