    "Hero": "بطل",
    "High-potential prospects across every position • including Israeli talents 🇮🇱": "مواهب ذات إمكانات عالية في جميع المراكز • بما في ذلك مواهب إسرائيلية 🇮🇱",
    "Icon": "أيقونة",
    "Israeli pride in FC 27: ": "فخر إسرائيلي في FC 27: ",
    "Lineup options": "خيارات التشكيلة",
    "Local date & time (YYYY-MM-DD HH:mm)": "التاريخ والوقت المحليان (YYYY-MM-DD HH:mm)",
    "Local date, optional (YYYY-MM-DD)": "التاريخ المحلي، اختياري (YYYY-MM-DD)",
    "MARK": "وضع علامة",
    "Mark only the highest grade you have already completed and claimed in the game. These are manual marks, without an EA account connection.": "حدد فقط أعلى تقييم أكملته وطالبت بمكافأته داخل اللعبة. هذه علامات يدوية دون اتصال بحساب EA.",
    "Meet the next generation of football: all 15 new Future Stars cards are here with ratings, attributes, statistics and market prices.": "تعرّف على الجيل القادم من كرة القدم: بطاقات Future Stars الجديدة الـ15 هنا مع التقييمات والسمات والإحصاءات وأسعار السوق.",
    "NEW IN THE CATALOGUE · 22 OCT 2026": "جديد في الكتالوج · 22 أكتوبر 2026",
    "New releases · 23–24 October": "إصدارات جديدة · 23–24 أكتوبر",
    "No matching sessions yet. Change the filters or set a time and invite friends with a link.": "لا توجد جلسات مطابقة بعد. غيّر الفلاتر أو حدد وقتًا وادعُ أصدقاءك برابط.",
    "No opted-in active days have been recorded yet. There is no basis for a return rate yet.": "لم تُسجّل أيام نشاط بموافقة المستخدمين بعد. لا يوجد أساس لحساب معدل العودة بعد.",
    "No purchases or rewards are performed here. Grade sets and claim tokens in the game.": "لا تتم عمليات شراء أو منح مكافآت هنا. قيّم المجموعات وطالب بالرموز داخل اللعبة.",
    "No ready-made lineup has passed our checks for this set yet. View the requirements or build your own plan.": "لم تجتز أي تشكيلة جاهزة فحوصاتنا لهذه المجموعة بعد. اعرض المتطلبات أو أنشئ خطتك الخاصة.",
    "Only accounts that opted in are counted. Administrator activity is excluded. Dates use Israel time.": "تُحتسب الحسابات التي وافقت فقط. يُستبعد نشاط المشرفين. تستخدم التواريخ توقيت إسرائيل.",
    "Only items eligible for this set are shown. Mark First Owner only if you packed or earned that edition yourself.": "تُعرض فقط العناصر المؤهلة لهذه المجموعة. حدد «المالك الأول» فقط إذا حصلت على تلك النسخة من حزمة أو مكافأة بنفسك.",
    "PC": "PC",
    "PLAY TOGETHER": "العبوا معًا",
    "Player-submitted profiles, matching by the game you love, and an easy way to start talking.": "ملفات يقدمها اللاعبون، ومطابقة حسب اللعبة التي تحبها، وطريقة سهلة لبدء الحديث.",
    "Players for this position. Search the full database in Hebrew or English.": "لاعبون لهذا المركز. ابحث في قاعدة البيانات الكاملة بالعبرية أو الإنجليزية.",
    "Rate squads across three categories. Packs are for sharing.": "قيّم التشكيلات في ثلاث فئات. الحزم للمشاركة.",
    "Reach the level with Season Points and claim the reward on the free track.": "صل إلى المستوى باستخدام نقاط الموسم وطالب بالمكافأة في المسار المجاني.",
    "Regular squad · Schedule a session": "تشكيلة منتظمة · جدولة جلسة",
    "Reputation points. They are not currency and cannot be withdrawn.": "نقاط سمعة. ليست عملة ولا يمكن سحبها.",
    "Results show base versions that meet this segment’s requirements. Points belong to the version shown.": "تعرض النتائج النسخ الأساسية التي تستوفي متطلبات هذا الجزء. تخص النقاط النسخة المعروضة.",
    "Return to the challenge to check availability, open its calculator or share an in-game screenshot.": "عد إلى التحدي للتحقق من توفره أو فتح حاسبته أو مشاركة لقطة شاشة من اللعبة.",
    "Ultimate Team": "Ultimate Team",
    "Untradeable objective reward · Earned through gameplay": "مكافأة أهداف غير قابلة للتداول · تُكتسب باللعب",
    "cm": "سم",
    "kg": "كغ",
    "Review the challenge segment, item versions and every requirement in the screenshot or squad before approving.": "راجع جزء التحدي ونسخ العناصر وكل المتطلبات في لقطة الشاشة أو التشكيلة قبل الموافقة.",
    "Route and progress saved on this device. Costs are recalculated when you return.": "يُحفظ المسار والتقدم على هذا الجهاز. يُعاد حساب التكاليف عند عودتك.",
    "Rules and milestones stay as published so everyone shares the same starting point. Progress is self-reported.": "تبقى القواعد والإنجازات كما نُشرت ليبدأ الجميع من النقطة نفسها. يبلّغ المشاركون عن تقدمهم بأنفسهم.",
    "Rush · Clubs · Co-op · Weekly squads": "Rush · Clubs · اللعب التعاوني · تشكيلات أسبوعية",
    "SBC solutions, players and Career challenges — start without an account.": "حلول تحديات بناء التشكيلة واللاعبون وتحديات المسيرة — ابدأ دون حساب.",
    "Season 2 Premium Pass access is also required. Season Points are not a coin price.": "يلزم أيضًا الوصول إلى تصريح Premium للموسم الثاني. نقاط الموسم ليست سعرًا بالعملات.",
    "Season 2 · All designs": "الموسم الثاني · جميع التصاميم",
    "Season 2 · Free Standard Pass": "الموسم الثاني · التصريح القياسي المجاني",
    "Season in my save": "الموسم في ملف حفظي",
    "Select a position and search for a player. To move a player, select their card, then the destination position.": "اختر مركزًا وابحث عن لاعب. لنقل لاعب، اختر بطاقته ثم مركز الوجهة.",
    "Select a win total to preview Coins, CQP, Tokens and available offers. This does not change your personal run.": "اختر عدد الانتصارات لمعاينة العملات وCQP والرموز والعروض المتاحة. لا يغيّر ذلك مشوارك الشخصي.",
    "Set the club, rules and goals. Everyone starts in their own save.": "حدد النادي والقواعد والأهداف. يبدأ كل شخص في ملف حفظه الخاص.",
    "Solution submitted for administrator review before publication. Uploading alone does not award XP.": "أُرسل الحل لمراجعة المشرف قبل النشر. الرفع وحده لا يمنح نقاط خبرة.",
    "Solutions are published only after administrator review. Uploading alone does not award XP.": "لا تُنشر الحلول إلا بعد مراجعة المشرف. الرفع وحده لا يمنح نقاط خبرة.",
    "Some detailed attributes for this Star Performer have not yet been verified against an FC 27 source.": "لم يتم بعد التحقق من بعض السمات التفصيلية لهذا اللاعب المتألق مقابل مصدر لـ FC 27.",
    "Some device marks could not be read. Check your progress before calculating.": "تعذر قراءة بعض العلامات على الجهاز. تحقق من تقدمك قبل الحساب.",
    "Squad · ": "التشكيلة · ",
    "Squads": "التشكيلات",
    "Start a journey": "ابدأ رحلة",
