    "Start time has passed": "مرّ وقت البداية",
    "Start with an empty pitch. Select a position, search for a player in English and add their card.": "ابدأ بملعب فارغ. اختر مركزًا وابحث عن لاعب بالإنجليزية وأضف بطاقته.",
    "Start with no items and 0 points. Search for a player and add only the items you choose.": "ابدأ دون عناصر وبـ 0 نقطة. ابحث عن لاعب وأضف العناصر التي تختارها فقط.",
    "Step": "الخطوة",
    "Still needed": "ما زال مطلوبًا",
    "TEKKZ is shown by default until community content is approved.": "يُعرض TEKKZ افتراضيًا حتى تتم الموافقة على محتوى المجتمع.",
    "THE GROUNDS · Independent FC 27 community": "THE GROUNDS · مجتمع FC 27 مستقل",
    "These are suggestions to browse. No items are added to your own selection.": "هذه اقتراحات للاستعراض. لا تُضاف أي عناصر إلى اختيارك الخاص.",
    "This SBC has expired and was automatically removed from the active list.": "انتهت صلاحية تحدي بناء التشكيلة هذا وأُزيل تلقائيًا من القائمة النشطة.",
    "This announcement appears once during the launch period": "يظهر هذا الإعلان مرة واحدة خلال فترة الإطلاق",
    "This card is a season reward, unavailable through SBCs or the transfer market.": "هذه البطاقة مكافأة موسم، ولا تتوفر عبر تحديات بناء التشكيلة أو سوق الانتقالات.",
    "This item pool is partial; an absent card is not necessarily ineligible.": "قائمة العناصر هذه جزئية؛ غياب بطاقة لا يعني بالضرورة أنها غير مؤهلة.",
    "This note is added to the journal without completing a milestone.": "تُضاف هذه الملاحظة إلى السجل دون إكمال إنجاز مرحلي.",
    "This section shows TEKKZ’s stats. Your record, CQP and progress appear in My Page.": "يعرض هذا القسم إحصاءات TEKKZ. يظهر سجلك وCQP وتقدمك في صفحتي.",
    "This solution is not published in the community. Ratings and rewards are available only after approval.": "لم يُنشر هذا الحل في المجتمع. لا تتوفر التقييمات والمكافآت إلا بعد الموافقة.",
    "View all recruitment": "عرض جميع إعلانات الاستقطاب",
    "View and choose lineup": "عرض التشكيلة واختيارها",
    "distinct items · no First Owner assumption": "عناصر مختلفة · دون افتراض أنها مملوكة لأول مرة",
    "e.g. Back to the Champions League": "مثال: العودة إلى دوري أبطال أوروبا",
    "e.g. Relaxed Rush objectives": "مثال: أهداف Rush الودية",
    "× means copies. For an option without duplicates, choose different players.": "تعني × عدد النسخ. لخيار دون تكرار، اختر لاعبين مختلفين.",
    "15 special cards": "15 بطاقة خاصة",
    "15–0 · Bronze squad": "15–0 · تشكيلة برونزية",
    "A Premium Pass is required to claim the Level 7 reward.": "يلزم تصريح Premium للمطالبة بمكافأة المستوى 7.",
    "A beta version for direct phone installation — not an app store release.": "نسخة تجريبية للتثبيت المباشر على الهاتف، وليست إصدارًا من متجر التطبيقات.",
