    "A row and a column. Name one player for every square.": "صف وعمود. اذكر لاعبًا واحدًا لكل خانة.",
    "Add a title, explanation and in-game grading screenshot. The screenshot score must match the calculation.": "أضف عنوانًا وشرحًا ولقطة شاشة للتقييم داخل اللعبة. يجب أن تطابق النتيجة في الصورة الحساب.",
    "Approved tactics and controller settings. Your uploads stay on your page while awaiting approval.": "التكتيكات وإعدادات وحدة التحكم المعتمدة. تبقى ملفاتك المرفوعة في صفحتك أثناء انتظار الموافقة.",
    "Badges are earned through Career approvals and Grounds listings.": "تُكتسب الشارات عبر الموافقات في المسيرة وإعلانات Grounds.",
    "Be the first to publish your player details and appear in the community.": "كن أول من ينشر تفاصيل لاعبه ويظهر في المجتمع.",
    "Budget, transfers, academy and difficulty. Specify if everyone must use the same club.": "الميزانية والانتقالات والأكاديمية ومستوى الصعوبة. حدد ما إذا كان على الجميع استخدام النادي نفسه.",
    "Build a squad by selecting positions and adding players to an empty pitch, or upload a screenshot from the game.": "أنشئ تشكيلة باختيار المراكز وإضافة اللاعبين إلى ملعب فارغ، أو ارفع لقطة شاشة من اللعبة.",
    "Build a squad from the site’s players: a starting XI and up to 7 substitutes.": "أنشئ تشكيلة من لاعبي الموقع: 11 لاعبًا أساسيًا وحتى 7 بدلاء.",
    "Build a squad with starters and substitutes. Visitors to your profile will see it on the pitch.": "أنشئ تشكيلة من لاعبين أساسيين وبدلاء. سيرى زوار ملفك الشخصي التشكيلة على الملعب.",
    "Build your squad from your profile — players on the pitch, with optional substitutes.": "أنشئ تشكيلتك من ملفك الشخصي — لاعبون على الملعب وبدلاء اختياريون.",
    "Choose a challenge to match its player eligibility and item scores.": "اختر تحديًا لمطابقة أهلية اللاعبين ونقاط العناصر معه.",
    "Choose a club and rules, play your own save and share the season with other players. Build the story one update at a time.": "اختر ناديًا وقواعد، والعب ملف حفظك الخاص وشارك الموسم مع لاعبين آخرين. ابنِ القصة تحديثًا تلو الآخر.",
    "Choose a formation, then build the squad for this post.": "اختر خطة لعب، ثم أنشئ تشكيلة هذا المنشور.",
    "Choose a goal or budget and plan around your sets and collected items.": "اختر هدفًا أو ميزانية وخطط بناءً على مجموعاتك والعناصر التي جمعتها.",
    "Choose a goal, play and share your progress with the community.": "اختر هدفًا، والعب وشارك تقدمك مع المجتمع.",
    "Choose a goal. Plan your next reward.": "اختر هدفًا. خطط لمكافأتك التالية.",
    "Coins to complete the challenge; this is not a market price for the card.": "العملات اللازمة لإكمال التحدي؛ هذا ليس سعر البطاقة في السوق.",
    "Collect items · Complete sets · Grade in game": "اجمع العناصر · أكمل المجموعات · قيّم داخل اللعبة",
    "Collected items refreshed. Recalculate to include them in your route.": "تم تحديث العناصر المجمّعة. أعد الحساب لإدراجها في مسارك.",
    "Community challenges are being prepared. They will appear here when available.": "يجري إعداد تحديات المجتمع. ستظهر هنا عندما تصبح متاحة.",
    "Complete a challenge, upload proof, and earn credit after approval. After 5 approvals, your submission is published immediately.": "أكمل تحديًا وارفع الإثبات واحصل على التقدير بعد الموافقة. بعد 5 موافقات، تُنشر مشاركتك فورًا.",
    "Complete the set and provide screenshots showing the items and in-game grade. Your submission remains private until administrator approval.": "أكمل المجموعة وقدّم لقطات شاشة تُظهر العناصر والتقييم داخل اللعبة. تبقى مشاركتك خاصة حتى موافقة المشرف.",
    "Console prices from the saved snapshot, not a live quote. Missing prices are never treated as zero.": "أسعار المنصات من اللقطة المحفوظة وليست أسعارًا مباشرة. لا تُعامل الأسعار المفقودة على أنها صفر.",
    "Controller settings for this post": "إعدادات وحدة التحكم لهذا المنشور",
    "Cost is the sum of the displayed player prices for your chosen platform. Market estimates can change. Items you already own do not require a purchase.": "التكلفة هي مجموع أسعار اللاعبين المعروضة للمنصة التي اخترتها. قد تتغير تقديرات السوق. العناصر التي تملكها بالفعل لا تحتاج إلى شراء.",
    "Country, language & kick-off": "الدولة واللغة ووقت البداية",
    "Cumulative tokens at the calculated grade, before deducting rewards already claimed.": "الرموز التراكمية عند التقييم المحسوب، قبل خصم المكافآت التي طُولب بها بالفعل.",
    "Data is saved on this device only.": "تُحفظ البيانات على هذا الجهاز فقط.",
    "Demo preview": "معاينة تجريبية",
    "Different players, no duplicates": "لاعبون مختلفون، دون تكرار",
    "Each account has its own run. Your progress is saved between visits.": "لكل حساب مشواره الخاص. يُحفظ تقدمك بين الزيارات.",
    "Empty position selected. Search below or select a player already on the pitch.": "تم اختيار مركز فارغ. ابحث أدناه أو اختر لاعبًا موجودًا في الملعب.",
    "Enter a title and a short explanation.": "أدخل عنوانًا وشرحًا موجزًا.",
