    "Win 2 matches while having Min. 2 Real Madrid (LALIGA) players in your starting 11 in the FC Heritage Circuit Semi-Pro Event.": "Vença 2 partidas com no mínimo 2 jogadores do Real Madrid (LALIGA) entre os titulares no evento Semiprofissional do FC Heritage Circuit.",
    "Score at least 2 goals in one match while having Min. 1 MLS player in your starting 11 in the FC Heritage Circuit Semi-Pro Event.": "Marque pelo menos 2 gols em uma partida com no mínimo 1 jogador da MLS entre os titulares no evento Semiprofissional do FC Heritage Circuit.",
    "Assist at least 3 goals while having Min. 1 Ligue 1 player in your starting 11 in the FC Heritage Circuit Semi-Pro Event.": "Dê pelo menos 3 assistências com no mínimo 1 jogador da Ligue 1 entre os titulares no evento Semiprofissional do FC Heritage Circuit.",
    "Score in 2 separate matches while having Min. 1 Serie A player in your starting 11 in the FC Heritage Circuit Semi-Pro Event.": "Marque em 2 partidas diferentes com no mínimo 1 jogador da Serie A entre os titulares no evento Semiprofissional do FC Heritage Circuit.",
    "Win 1 match in the FC Heritage Circuit Semi-Pro Event and qualify for the FC Heritage Circuit Professional Event.": "Vença 1 partida no evento Semiprofissional do FC Heritage Circuit e classifique-se para o evento Profissional.",
    "Win 2 matches while having Min. 3 Premier League players in your starting 11 in the FC Heritage Circuit Professional Event.": "Vença 2 partidas com no mínimo 3 jogadores da Premier League entre os titulares no evento Profissional do FC Heritage Circuit.",
    "Score at least 3 goals in one match while having Min. 1 French player in your starting 11 in the FC Heritage Circuit Professional Event.": "Marque pelo menos 3 gols em uma partida com no mínimo 1 jogador francês entre os titulares no evento Profissional do FC Heritage Circuit.",
    "Assist at least 3 goals while having Min. 1 Belgian player in your starting 11 in the FC Heritage Circuit Professional Event.": "Dê pelo menos 3 assistências com no mínimo 1 jogador belga entre os titulares no evento Profissional do FC Heritage Circuit.",
    "Score at least 1 goal in 2 separate matches while having Min. 1 English player in your starting 11 in the FC Heritage Circuit Professional Event.": "Marque pelo menos 1 gol em 2 partidas diferentes com no mínimo 1 jogador inglês entre os titulares no evento Profissional do FC Heritage Circuit.",
    "Win 1 match in the FC Heritage Circuit Professional Event and qualify for the FC Heritage Circuit World Class Event.": "Vença 1 partida no evento Profissional do FC Heritage Circuit e classifique-se para o evento Classe Mundial.",
    "Win 3 matches while having Min. 3 player items from Bundesliga in your starting 11 in the FC Heritage Circuit World Class Event.": "Vença 3 partidas com no mínimo 3 itens de jogadores da Bundesliga entre os titulares no evento Classe Mundial do FC Heritage Circuit.",
    "Score 5 goals while having Min. 1 FC Bayern München (Bundesliga) player item in your starting 11 in the FC Heritage Circuit World Class Event.": "Marque 5 gols com no mínimo 1 item de jogador do FC Bayern München (Bundesliga) entre os titulares no evento Classe Mundial do FC Heritage Circuit.",
    "Assist 4 goals while having Min. 1 PSG (Ligue 1) player item in your starting 11 in the FC Heritage Circuit World Class Event.": "Dê 4 assistências com no mínimo 1 item de jogador do PSG (Ligue 1) entre os titulares no evento Classe Mundial do FC Heritage Circuit.",
    "Score at least 1 goal in 3 separate matches while having Min. 1 Real Madrid (LALIGA) player item in your starting 11 in the FC Heritage Circuit World Class Event.": "Marque pelo menos 1 gol em 3 partidas diferentes com no mínimo 1 item de jogador do Real Madrid (LALIGA) entre os titulares no evento Classe Mundial do FC Heritage Circuit.",
    "Win 1 match in the FC Heritage Circuit World Class Event and qualify for the FC Heritage Circuit Tournament.": "Vença 1 partida no evento Classe Mundial do FC Heritage Circuit e classifique-se para o Torneio FC Heritage Circuit.",
