    "Compete in the FC Heritage Circuit Tournament to earn a special FC Heritage Alexis Sánchez, packs and more. All rewards are untradeable.": "Participe do Torneio FC Heritage Circuit para ganhar uma carta especial FC Heritage de Alexis Sánchez, pacotes e mais. Todas as recompensas são inegociáveis.",
    "Win the FC Heritage Circuit Tournament 3 times.": "Vença o Torneio FC Heritage Circuit 3 vezes.",
    "Win the FC Heritage Circuit Tournament while having Min. 2 Premier League players in your starting 11.": "Vença o Torneio FC Heritage Circuit com no mínimo 2 jogadores da Premier League entre os 11 titulares.",
    "Win 2 matches while having Min. 2 Ligue 1 players in your starting 11 in the FC Heritage Circuit Tournament.": "Vença 2 partidas com no mínimo 2 jogadores da Ligue 1 entre os 11 titulares no Torneio FC Heritage Circuit.",
    "Assist at least 1 goal in 3 separate matches while having Min. 1 Dutch player in your starting 11 in the FC Heritage Circuit Tournament.": "Dê assistência para pelo menos 1 gol em 3 partidas diferentes com no mínimo 1 jogador neerlandês entre os titulares no Torneio FC Heritage Circuit.",
    "Score at least 1 goal in 3 separate matches while having Min. 1 Real Madrid (LALIGA) player in your starting 11 in the FC Heritage Circuit Tournament.": "Marque pelo menos 1 gol em 3 partidas diferentes com no mínimo 1 jogador do Real Madrid (LALIGA) entre os titulares no Torneio FC Heritage Circuit.",
    "Score at least 2 goals in 1 match while having Min. 1 French player in your starting 11 in the FC Heritage Circuit Tournament.": "Marque pelo menos 2 gols em 1 partida com no mínimo 1 jogador francês entre os titulares no Torneio FC Heritage Circuit.",
    "Win 1 Quarter-Finals match while having Min. 2 Serie A players in your starting 11 in the FC Heritage Circuit Tournament.": "Vença 1 partida das quartas de final com no mínimo 2 jogadores da Serie A entre os titulares no Torneio FC Heritage Circuit.",
    "Complete the FC Heritage Circuit Objectives to earn rewards. All rewards are untradeable.": "Conclua os objetivos do FC Heritage Circuit para ganhar recompensas. Todas são inegociáveis.",
