    "D is the first grade, followed by C, B, A and S, the highest. Every slot must be filled. Thresholds vary by set and rewards are cumulative.": "D é a primeira nota, seguida por C, B, A e S, a mais alta. Todas as vagas devem ser preenchidas. Os limites variam por conjunto e as recompensas são cumulativas.",
    "Day 1 and Day 7 are measured from the first observed active day, not a historical signup date. Rates start when the required return day is reached; the current day is still partial.": "O dia 1 e o dia 7 são medidos a partir do primeiro dia ativo observado, não da data histórica de cadastro. As taxas começam quando o dia de retorno necessário é alcançado; o dia atual ainda está incompleto.",
    "Day 1 return: ": "Retorno no dia 1: ",
