    "Drag in any direction — the area inside the circle will appear on your card": "Arraste em qualquer direção — a área dentro do círculo aparecerá na sua carta",
    "EA FC chemistry: up to three diamonds per player based on club, nation and league links. An incorrect position gives 0. Maximum total: 33.": "Entrosamento do EA FC: até três losangos por jogador conforme as ligações de clube, nacionalidade e liga. Uma posição incorreta dá 0. Total máximo: 33.",
    "Each option is checked for item count, grade thresholds and bonuses. This is calculation validation; in-game evidence is reviewed separately for community solutions.": "Cada opção é verificada quanto à quantidade de itens, limites de nota e bônus. Isso valida o cálculo; as provas no jogo são analisadas separadamente para soluções da comunidade.",
    "Ends in ": "Termina em ",
    "Everyone is in black and white. Tap only the player who matches. Correct answers stay in color.": "Todos estão em preto e branco. Toque apenas no jogador correspondente. As respostas corretas ficam coloridas.",
    "Everyone plays their own save. Self-reported progress, without EA account sync or points for marking milestones.": "Cada pessoa joga sua própria carreira. O progresso é informado pelo participante, sem sincronização com a conta EA ou pontos por marcar marcos.",
