    "Meet the next generation of football: all 15 new Future Stars cards are here with ratings, attributes, statistics and market prices.": "Conheça a próxima geração do futebol: as 15 novas cartas Future Stars estão aqui com notas, atributos, estatísticas e preços de mercado.",
