    "Could not save. Please try again.": "Não foi possível salvar. Tente novamente.",
    "Could not update your follow list. Sign in and try again.": "Não foi possível atualizar sua lista de seguidos. Entre na conta e tente novamente.",
    "Could not update your follow status. Try again.": "Não foi possível atualizar seu status de seguimento. Tente novamente.",
    "Please try again shortly. You can keep exploring the rest of the site.": "Tente novamente em instantes. Você pode continuar explorando o restante do site.",
    "Hello ONE CLUB,\nPlease delete my account and its associated data.\nAccount email:\nDisplay name (optional):": "Olá, ONE CLUB,\nSolicito a exclusão da minha conta e dos dados associados a ela.\nE-mail da conta:\nNome de exibição (opcional):",
    "ONE CLUB — Account and data deletion": "ONE CLUB — Exclusão de conta e dados",
    "Request deletion of your ONE CLUB account and its associated data here, without signing in or reinstalling the app.": "Solicite aqui a exclusão da sua conta ONE CLUB e dos dados associados, sem entrar na conta ou reinstalar o aplicativo.",
    "1. Email us from the address registered to your account, requesting account and data deletion. If you cannot access that address, explain this so we can discuss another way to verify ownership.": "1. Envie um e-mail do endereço cadastrado na sua conta solicitando a exclusão da conta e dos dados. Se você não tiver acesso a esse endereço, informe isso para que possamos discutir outra forma de verificar a titularidade.",
    "If no email app opens, copy the address and send a message from your email service.": "Se nenhum aplicativo de e-mail abrir, copie o endereço e envie uma mensagem pelo seu serviço de e-mail.",
    "2. We verify account ownership before processing the request. Do not send passwords or verification codes.": "2. Verificamos a titularidade da conta antes de processar a solicitação. Não envie senhas ou códigos de verificação.",
    "3. The request covers your account, profile and associated data, including content and photos you uploaded. Sending a request starts a review; clicking the link does not immediately delete your account.": "3. A solicitação abrange sua conta, perfil e dados associados, incluindo conteúdos e fotos enviados por você. O envio inicia uma análise; clicar no link não exclui sua conta imediatamente.",
    "As described in our privacy policy, information subject to a legal retention obligation may be retained. If this applies to your request, we will explain what is retained, why and for how long in our response.": "Conforme descrito em nossa política de privacidade, informações sujeitas a uma obrigação legal de retenção podem ser mantidas. Se isso se aplicar à sua solicitação, explicaremos na resposta o que será mantido, por quê e por quanto tempo.",
    "Terms approval required • LEGAL CONSENT": "É necessário aceitar os termos • CONSENTIMENTO LEGAL",
    "Welcome to FC27 Israel!": "Boas-vindas ao FC27 Israel!",
    "Hello {name}, please read and accept the current Terms of Use and Privacy Policy before using the app.": "Olá, {name}. Leia e aceite os Termos de Uso e a Política de Privacidade atuais antes de usar o aplicativo.",
    "This site is not affiliated with, endorsed, or supported by Electronic Arts Inc. All brands, game names, and player images belong to their respective owners and are used under applicable fair-use principles.": "Este site não é afiliado, aprovado ou apoiado pela Electronic Arts Inc. Todas as marcas, nomes de jogos e imagens de jogadores pertencem aos respectivos proprietários e são usados conforme os princípios aplicáveis de uso justo.",
    "Real-money trading is prohibited:": "É proibido negociar por dinheiro real:",
    "Trading game coins, accounts, or virtual assets for real money is strictly prohibited.": "É estritamente proibido negociar moedas do jogo, contas ou ativos virtuais por dinheiro real.",
    "Privacy and safety:": "Privacidade e segurança:",
    "We do not sell personal information. Users under 18 may use the site only with parent or legal-guardian consent.": "Não vendemos informações pessoais. Menores de 18 anos só podem usar o site com o consentimento de um dos pais ou responsável legal.",
    "I have read, understood, and agree to the 1 CLUB Terms of Use and Privacy Policy.": "Li, compreendi e concordo com os Termos de Uso e a Política de Privacidade do 1 CLUB.",
    "⚠️ Please check the box above to accept the terms and enter the app.": "⚠️ Marque a caixa acima para aceitar os termos e entrar no aplicativo.",
    "I do not agree (sign out and exit)": "Não concordo (sair da conta e fechar)",
    "Cookies and browser storage": "Cookies e armazenamento no navegador",
    "Device storage": "Armazenamento no dispositivo",
    "1 CLUB stores only what is needed to keep you signed in and remember that you have seen this notice. We do not use advertising cookies. You can keep browsing without clicking this notice, and sign-in will continue to work.": "O 1 CLUB armazena apenas o necessário para manter sua sessão ativa e lembrar que você viu este aviso. Não usamos cookies de publicidade. Você pode continuar navegando sem clicar neste aviso, e o login continuará funcionando.",
    "Cookie details": "Detalhes dos cookies",
    "Change the site language at any time. Your choice is saved for future visits.": "Altere o idioma do site a qualquer momento. Sua escolha será salva para as próximas visitas.",
    "Request account and data deletion": "Solicitar exclusão da conta e dos dados",
    "Optionally share one active day per signed-in account, without page history or advertising. Turning this off stops measurement on this device.": "Opcionalmente, compartilhe um dia de atividade por conta conectada, sem histórico de páginas ou publicidade. Ao desativar, a medição é interrompida neste dispositivo.",
    "Terms acceptance required": "É necessário aceitar os termos",
