    "Score at least 3 goals in one match while having Min. 1 French player in your starting 11 in the FC Heritage Circuit Professional Event.": "Marca al menos 3 goles en un partido con al menos 1 jugador francés en el once inicial del evento Profesional de FC Heritage Circuit.",
    "Assist at least 3 goals while having Min. 1 Belgian player in your starting 11 in the FC Heritage Circuit Professional Event.": "Da al menos 3 asistencias con al menos 1 jugador belga en el once inicial del evento Profesional de FC Heritage Circuit.",
    "Score at least 1 goal in 2 separate matches while having Min. 1 English player in your starting 11 in the FC Heritage Circuit Professional Event.": "Marca al menos 1 gol en 2 partidos distintos con al menos 1 jugador inglés en el once inicial del evento Profesional de FC Heritage Circuit.",
    "Win 1 match in the FC Heritage Circuit Professional Event and qualify for the FC Heritage Circuit World Class Event.": "Gana 1 partido en el evento Profesional de FC Heritage Circuit y clasifícate para el evento Clase mundial.",
    "Win 3 matches while having Min. 3 player items from Bundesliga in your starting 11 in the FC Heritage Circuit World Class Event.": "Gana 3 partidos con al menos 3 artículos de jugadores de la Bundesliga en el once inicial del evento Clase mundial de FC Heritage Circuit.",
    "Score 5 goals while having Min. 1 FC Bayern München (Bundesliga) player item in your starting 11 in the FC Heritage Circuit World Class Event.": "Marca 5 goles con al menos 1 artículo de jugador del FC Bayern München (Bundesliga) en el once inicial del evento Clase mundial de FC Heritage Circuit.",
    "Assist 4 goals while having Min. 1 PSG (Ligue 1) player item in your starting 11 in the FC Heritage Circuit World Class Event.": "Da 4 asistencias con al menos 1 artículo de jugador del PSG (Ligue 1) en el once inicial del evento Clase mundial de FC Heritage Circuit.",
