    "Compete in the FC Heritage Circuit Tournament to earn a special FC Heritage Alexis Sánchez, packs and more. All rewards are untradeable.": "Compite en el Torneo FC Heritage Circuit para conseguir una carta especial de Alexis Sánchez de FC Heritage, sobres y más. Todas las recompensas son intransferibles.",
