    "Assist at least 1 goal in 3 separate matches while having Min. 1 Dutch player in your starting 11 in the FC Heritage Circuit Tournament.": "Da al menos 1 asistencia en 3 partidos distintos con al menos 1 jugador neerlandés en el once inicial del Torneo FC Heritage Circuit.",
    "Score at least 1 goal in 3 separate matches while having Min. 1 Real Madrid (LALIGA) player in your starting 11 in the FC Heritage Circuit Tournament.": "Marca al menos 1 gol en 3 partidos distintos con al menos 1 jugador del Real Madrid (LALIGA) en el once inicial del Torneo FC Heritage Circuit.",
