    "D is the first grade, followed by C, B, A and S, the highest. Every slot must be filled. Thresholds vary by set and rewards are cumulative.": "D es la primera nota, seguida de C, B, A y S, la más alta. Hay que llenar todas las casillas. Los umbrales varían según el conjunto y las recompensas son acumulativas.",
    "Day 1 and Day 7 are measured from the first observed active day, not a historical signup date. Rates start when the required return day is reached; the current day is still partial.": "El día 1 y el día 7 se miden desde el primer día activo observado, no desde la fecha histórica de registro. Las tasas empiezan cuando se alcanza el día de regreso requerido; el día actual aún está incompleto.",
    "Day 1 return: ": "Retorno el día 1: ",
