    "Drag in any direction — the area inside the circle will appear on your card": "Arrastra en cualquier dirección: el área dentro del círculo aparecerá en tu carta",
    "EA FC chemistry: up to three diamonds per player based on club, nation and league links. An incorrect position gives 0. Maximum total: 33.": "Química de EA FC: hasta tres rombos por jugador según sus vínculos de club, país y liga. Una posición incorrecta da 0. Total máximo: 33.",
    "Each option is checked for item count, grade thresholds and bonuses. This is calculation validation; in-game evidence is reviewed separately for community solutions.": "Cada opción se comprueba por cantidad de artículos, umbrales de nota y bonificaciones. Esto valida el cálculo; las pruebas del juego se revisan por separado para las soluciones de la comunidad.",
    "Ends in ": "Termina en ",
    "Everyone is in black and white. Tap only the player who matches. Correct answers stay in color.": "Todos aparecen en blanco y negro. Pulsa solo al jugador que coincida. Las respuestas correctas permanecen en color.",
    "Everyone plays their own save. Self-reported progress, without EA account sync or points for marking milestones.": "Cada persona juega su propia partida. El progreso lo declara el participante, sin sincronización con la cuenta EA ni puntos por marcar hitos.",
