    "Mark only the highest grade you have already completed and claimed in the game. These are manual marks, without an EA account connection.": "Marca solo la nota más alta que ya hayas completado y reclamado en el juego. Son marcas manuales, sin conexión con una cuenta EA.",
    "Meet the next generation of football: all 15 new Future Stars cards are here with ratings, attributes, statistics and market prices.": "Conoce a la próxima generación del fútbol: las 15 nuevas cartas Future Stars están aquí con valoraciones, atributos, estadísticas y precios de mercado.",
