    "No opted-in active days have been recorded yet. There is no basis for a return rate yet.": "Aún no se han registrado días activos de usuarios que hayan aceptado. Todavía no hay base para calcular una tasa de retorno.",
    "No purchases or rewards are performed here. Grade sets and claim tokens in the game.": "Aquí no se realizan compras ni se conceden recompensas. Obtén notas para los conjuntos y reclama fichas en el juego.",
    "No ready-made lineup has passed our checks for this set yet. View the requirements or build your own plan.": "Ninguna alineación preparada ha superado aún nuestras comprobaciones para este conjunto. Consulta los requisitos o crea tu propio plan.",
    "Only accounts that opted in are counted. Administrator activity is excluded. Dates use Israel time.": "Solo se cuentan las cuentas que han aceptado. Se excluye la actividad de los administradores. Las fechas usan la hora de Israel.",
    "Only items eligible for this set are shown. Mark First Owner only if you packed or earned that edition yourself.": "Solo se muestran artículos válidos para este conjunto. Marca Primer propietario únicamente si obtuviste esa edición tú mismo en un sobre o como recompensa.",
