    "Could not save. Please try again.": "No se pudo guardar. Vuelve a intentarlo.",
    "Could not update your follow list. Sign in and try again.": "No se pudo actualizar tu lista de seguidos. Inicia sesión y vuelve a intentarlo.",
    "Could not update your follow status. Try again.": "No se pudo actualizar tu estado de seguimiento. Vuelve a intentarlo.",
    "Please try again shortly. You can keep exploring the rest of the site.": "Vuelve a intentarlo dentro de poco. Puedes seguir explorando el resto del sitio.",
    "Hello ONE CLUB,\nPlease delete my account and its associated data.\nAccount email:\nDisplay name (optional):": "Hola, ONE CLUB:\nSolicito la eliminación de mi cuenta y de los datos asociados.\nCorreo electrónico de la cuenta:\nNombre visible (opcional):",
    "ONE CLUB — Account and data deletion": "ONE CLUB — Eliminación de cuenta y datos",
    "Request deletion of your ONE CLUB account and its associated data here, without signing in or reinstalling the app.": "Solicita aquí la eliminación de tu cuenta de ONE CLUB y sus datos asociados, sin iniciar sesión ni volver a instalar la aplicación.",
    "1. Email us from the address registered to your account, requesting account and data deletion. If you cannot access that address, explain this so we can discuss another way to verify ownership.": "1. Envíanos un correo desde la dirección registrada en tu cuenta solicitando la eliminación de la cuenta y los datos. Si no tienes acceso a esa dirección, indícalo para que podamos estudiar otra forma de verificar que la cuenta es tuya.",
    "If no email app opens, copy the address and send a message from your email service.": "Si no se abre ninguna aplicación de correo, copia la dirección y envía un mensaje desde tu servicio de correo.",
    "2. We verify account ownership before processing the request. Do not send passwords or verification codes.": "2. Verificamos la titularidad de la cuenta antes de tramitar la solicitud. No envíes contraseñas ni códigos de verificación.",
    "3. The request covers your account, profile and associated data, including content and photos you uploaded. Sending a request starts a review; clicking the link does not immediately delete your account.": "3. La solicitud abarca tu cuenta, perfil y datos asociados, incluido el contenido y las fotos que hayas subido. El envío inicia una revisión; pulsar el enlace no elimina la cuenta inmediatamente.",
    "As described in our privacy policy, information subject to a legal retention obligation may be retained. If this applies to your request, we will explain what is retained, why and for how long in our response.": "Como se describe en nuestra política de privacidad, es posible que se conserve la información sujeta a una obligación legal de conservación. Si esto se aplica a tu solicitud, explicaremos en la respuesta qué se conserva, por qué y durante cuánto tiempo.",
    "Terms approval required • LEGAL CONSENT": "Debes aceptar los términos • CONSENTIMIENTO LEGAL",
    "Welcome to FC27 Israel!": "¡Te damos la bienvenida a FC27 Israel!",
    "Hello {name}, please read and accept the current Terms of Use and Privacy Policy before using the app.": "Hola, {name}. Lee y acepta los Términos de uso y la Política de privacidad actuales antes de usar la aplicación.",
    "This site is not affiliated with, endorsed, or supported by Electronic Arts Inc. All brands, game names, and player images belong to their respective owners and are used under applicable fair-use principles.": "Este sitio no está afiliado a Electronic Arts Inc. ni cuenta con su aprobación o apoyo. Todas las marcas, nombres de juegos e imágenes de jugadores pertenecen a sus respectivos propietarios y se utilizan conforme a los principios aplicables de uso legítimo.",
    "Real-money trading is prohibited:": "Se prohíbe el comercio con dinero real:",
    "Trading game coins, accounts, or virtual assets for real money is strictly prohibited.": "Está estrictamente prohibido comerciar con monedas del juego, cuentas o activos virtuales a cambio de dinero real.",
    "Privacy and safety:": "Privacidad y seguridad:",
    "We do not sell personal information. Users under 18 may use the site only with parent or legal-guardian consent.": "No vendemos información personal. Los menores de 18 años solo pueden usar el sitio con el consentimiento de un padre, madre o tutor legal.",
    "I have read, understood, and agree to the 1 CLUB Terms of Use and Privacy Policy.": "He leído, comprendido y acepto los Términos de uso y la Política de privacidad de 1 CLUB.",
    "⚠️ Please check the box above to accept the terms and enter the app.": "⚠️ Marca la casilla de arriba para aceptar los términos y entrar en la aplicación.",
    "I do not agree (sign out and exit)": "No acepto (cerrar sesión y salir)",
    "Cookies and browser storage": "Cookies y almacenamiento del navegador",
    "Device storage": "Almacenamiento en el dispositivo",
    "1 CLUB stores only what is needed to keep you signed in and remember that you have seen this notice. We do not use advertising cookies. You can keep browsing without clicking this notice, and sign-in will continue to work.": "1 CLUB solo almacena lo necesario para mantener tu sesión iniciada y recordar que has visto este aviso. No usamos cookies publicitarias. Puedes seguir navegando sin pulsar este aviso y el inicio de sesión seguirá funcionando.",
    "Cookie details": "Detalles de las cookies",
    "Change the site language at any time. Your choice is saved for future visits.": "Puedes cambiar el idioma del sitio en cualquier momento. Tu elección se guarda para futuras visitas.",
    "Request account and data deletion": "Solicitar la eliminación de la cuenta y los datos",
    "Optionally share one active day per signed-in account, without page history or advertising. Turning this off stops measurement on this device.": "Puedes compartir un día de actividad por cuenta con sesión iniciada, sin historial de páginas ni publicidad. Al desactivarlo, se detiene la medición en este dispositivo.",
    "Terms acceptance required": "Debes aceptar los términos",
